public class CategoryPlot_removeRangeMarker_TriageGen0Test {

    private CategoryPlot plot;
    private Marker mockMarker;
    private Map<Integer, ArrayList> foregroundMarkers;
    private Map<Integer, ArrayList> backgroundMarkers;

    @Before
    public void setUp() throws Exception {
        plot = new CategoryPlot();
        mockMarker = mock(Marker.class);

        // Use reflection to access private fields foregroundRangeMarkers and backgroundRangeMarkers
        // Since the method uses .get(new Integer(index)), these must be Maps (likely HashMaps) 
        // containing ArrayLists as values.
        foregroundMarkers = new HashMap<>();
        backgroundMarkers = new HashMap<>();

        setPrivateField(plot, "foregroundRangeMarkers", foregroundMarkers);
        setPrivateField(plot, "backgroundRangeMarkers", backgroundMarkers);
    }

    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRemoveRangeMarker_NullMarker() {
        plot.removeRangeMarker(0, null, Layer.FOREGROUND, true);
    }

    @Test
    public void testRemoveRangeMarker_Foreground_Success_WithNotify() {
        int index = 0;
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);
        foregroundMarkers.put(index, list);

        // Note: We cannot easily verify fireChangeEvent() unless we mock the plot 
        // or check side effects. Given the constraints, we test the return value.
        boolean result = plot.removeRangeMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertTrue("Marker should have been removed", result);
        assertTrue("List should be empty", list.isEmpty());
    }

    @Test
    public void testRemoveRangeMarker_Foreground_Failure() {
        int index = 0;
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mock(Marker.class)); // Different marker
        foregroundMarkers.put(index, list);

        boolean result = plot.removeRangeMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertFalse("Result should be false when marker not found", result);
        assertEquals(1, list.size());
    }

    @Test
    public void testRemoveRangeMarker_Background_Success_NoNotify() {
        int index = 1;
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);
        backgroundMarkers.put(index, list);

        boolean result = plot.removeRangeMarker(index, mockMarker, Layer.BACKGROUND, false);

        assertTrue("Marker should have been removed", result);
        assertTrue(list.isEmpty());
    }

    @Test
    public void testRemoveRangeMarker_Background_Failure() {
        int index = 5;
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mock(Marker.class));
        backgroundMarkers.put(index, list);

        boolean result = plot.removeRangeMarker(index, mockMarker, Layer.BACKGROUND, true);

        assertFalse("Result should be false", result);
    }

    @Test(expected = NullPointerException.class)
    public void testRemoveRangeMarker_IndexNotFound_Foreground() {
        // This tests the case where the index does not exist in the map, causing .get() to return null
        plot.removeRangeMarker(99, mockMarker, Layer.FOREGROUND, true);
    }

    @Test(expected = NullPointerException.class)
    public void testRemoveRangeMarker_IndexNotFound_Background() {
        plot.removeRangeMarker(99, mockMarker, Layer.BACKGROUND, true);
    }
}
